package org.example.userservice.controller;import lombok.RequiredArgsConstructor;import org.example.userservice.dto.AuthResponseDto;import org.example.userservice.dto.LoginDto;import org.example.userservice.dto.SaveUserDto;import org.example.userservice.dto.UserDto;import org.example.userservice.service.UserService;import org.springframework.data.domain.Page;import org.springframework.data.domain.Pageable;import org.springframework.data.domain.Sort;import org.springframework.data.web.PageableDefault;import org.springframework.http.HttpStatus;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.GetMapping;import org.springframework.web.bind.annotation.PathVariable;import org.springframework.web.bind.annotation.PostMapping;import org.springframework.web.bind.annotation.RequestBody;import org.springframework.web.bind.annotation.RequestMapping;import org.springframework.web.bind.annotation.RestController;@RestController@RequiredArgsConstructor@RequestMapping("/users")public class UserController {    private final UserService userService;    @PostMapping("/register")    public ResponseEntity<UserDto> saveUser(@RequestBody SaveUserDto saveUserDto) {        return ResponseEntity.status(HttpStatus.CREATED).body(userService.register(saveUserDto));    }    @PostMapping("/login")    public ResponseEntity<AuthResponseDto> login(@RequestBody LoginDto loginDto) {        return ResponseEntity.ok(userService.login(loginDto));    }    @GetMapping("/{id}")    public UserDto getById(@PathVariable Long id) {        return userService.getById(id);    }    @GetMapping    public Page<UserDto> getAll(@PageableDefault(size = 4,sort = "id",direction = Sort.Direction.ASC) Pageable pageable) {        return userService.getAll(pageable);    }}